const m=new Intl.DateTimeFormat("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:!1}),d=new Intl.DateTimeFormat("zh-CN",{month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hour12:!1});function u(e){const t=e instanceof Date?e:new Date(e);return Number.isNaN(t.getTime())?void 0:t}function h(e){const t=u(e);return t?m.format(t).replaceAll("/","-"):"—"}function c(e){const t=u(e);return t?d.format(t).replaceAll("/","-"):"—"}function f(e,t=Date.now()){const o=u(e);if(!o)return"—";const i=Math.round((o.getTime()-t)/1e3),n=Math.abs(i);if(n<60)return i<=0?"刚刚":"片刻后";const a=Math.round(i/60);if(n<3600)return a<0?`${Math.abs(a)} 分钟前`:`${a} 分钟后`;const r=Math.round(a/60);if(n<86400)return r<0?`${Math.abs(r)} 小时前`:`${r} 小时后`;const s=Math.round(r/24);return n<604800?s<0?`${Math.abs(s)} 天前`:`${s} 天后`:c(o)}export{f as a,c as b,h as f};
